INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '提前与延后', 'kp-eng-t-advance-delay', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "提前与延后问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "实际时间与计划时间的差值比较。建立在效率变化或中途停工的基础上。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经常出现的问法：“如果想提前 3 天完工，应该……”或“由于停电了 2 天，最终延后了几天完工？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心等量关系"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论怎么提前或延后，【总工程量是死的】。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{原} \\times T_{原} = P_{新} \\times T_{新}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确题目给出的原计划 P原 和 T原] --> B[利用突变条件算出 P新 或 新要求的 T新]\nB --> C[利用工程总量守恒, 倒推另一个变量]\nC --> D[将实际花费的总时间与原计划总时间做减法]\nD --> E[正数为延后, 负数为提前]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 计划 30 天完成。干了 10 天后，因为材料短缺停工 5 天。复工后效率提升了 50%。问最终比原计划提前还是延后了几天？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋基准：令原效率为 2，W = 2 × 30 = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "前阶段：10 天完成 10 × 2 = 20。剩下 W余 = 40。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "停工段：耗费 5 天，进度 0。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "复工段：效率提升50%（变成1.5倍），新效率 = 2 × 1.5 = 3。剩下 40 的活，需要耗时 = 40 ÷ 3 = 13.33 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总耗时：实际总共花了 10(开局) + 5(停工) + 13.33(复工) = 28.33 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结论：原计划 30 天。30 - 28.33 = 1.67。提前了 1.67 天。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记算停工的天数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生算出开局10天，复工13.3天，一加等于23.3天，一看比30天提前了6.7天。彻底忘了中间停电/下雨的那 5 天也是真真实实流逝的时间！这 5 天必须加进总耗时里！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "凡是有“停工”字眼的，立刻拿红笔画个大大的圈。算实际总用时的时候，必须把这个数字捡回来加上。"}]}]}$$ AS jsonb), NULL, '提前与延后的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "提前与延后"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_t_advance_delay", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
